<section class="page-heading"><p class="eyebrow">RESTRICTED ACCESS · ADMIN</p><h1>Operations.</h1><p>Manage MAPIDO accounts and review incoming reports.</p></section><section class="admin-stats"><div><small>REGISTERED USERS</small><strong><?= (int)$data['stats']['users'] ?></strong></div><div><small>PUBLISHED RIDES</small><strong><?= (int)$data['stats']['rides'] ?></strong></div><div><small>BOOKING REQUESTS</small><strong><?= (int)$data['stats']['bookings'] ?></strong></div><div><small>OPEN REPORTS</small><strong><?= count(array_filter($data['complaints'],fn($c)=>$c['status']==='Open')) ?></strong></div></section>
<section class="admin-section"><div class="section-head"><h2>Accounts</h2><span>Latest 100</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($data['users'] as $account): ?><tr><td><?= e($account['name']) ?></td><td><?= e($account['email']) ?></td><td><?= e(ucfirst($account['role'])) ?></td><td><?= $account['is_suspended']?'Suspended':'Active' ?></td><td><?= e(date('M j, Y',strtotime($account['created_at']))) ?></td><td><?php if($account['role']!=='admin'): ?><form method="post" data-confirm="<?= $account['is_suspended']?'Restore':'Suspend' ?> this account?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="suspend_user"><input type="hidden" name="suspend" value="<?= $account['is_suspended']?0:1 ?>"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="user_id" value="<?= (int)$account['id'] ?>"><button class="btn btn-link btn-sm <?= $account['is_suspended']?'':'text-danger' ?>"><?= $account['is_suspended']?'Restore':'Suspend' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-section"><div class="section-head"><h2>Reports & complaints</h2><span>Latest 100</span></div><?php if(!$data['complaints']): ?><p class="muted">No reports have been submitted.</p><?php endif; ?><?php foreach($data['complaints'] as $complaint): ?><article class="complaint-row"><div><span class="status status-<?= strtolower($complaint['status']) ?>"><?= e($complaint['status']) ?></span> <span class="kind-tag"><?= e($complaint['kind']) ?></span><h3><?= e($complaint['subject']) ?></h3><p><?= nl2br(e($complaint['body'])) ?></p><small><?= e($complaint['user_name']??$complaint['contact_email']) ?> · <?= e(date('M j, Y g:i a',strtotime($complaint['created_at']))) ?></small></div><?php if($complaint['status']==='Open'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="resolve_complaint"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="complaint_id" value="<?= (int)$complaint['id'] ?>"><button class="btn btn-outline-dark btn-sm">Mark resolved</button></form><?php endif; ?></article><?php endforeach; ?></section>
<section class="admin-section"><div class="section-head"><h2>Reported reviews</h2><span><?= count($data['reported_reviews']) ?> open reports</span></div><?php if(!$data['reported_reviews']): ?><p class="muted">No reviews have been reported.</p><?php endif; ?><?php foreach($data['reported_reviews'] as $review): ?><article class="complaint-row"><div><span class="review-stars"><?= str_repeat('★',(int)$review['rating']) ?></span><h3><?= e($review['reviewer_name']) ?> reviewed <?= e($review['target_name']) ?></h3><p><?= e($review['comment']) ?></p><small><?= e($review['origin']) ?> → <?= e($review['destination']) ?> · <?= e(date('M j, Y',strtotime($review['created_at']))) ?></small></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="moderate_review"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="review_id" value="<?= (int)$review['id'] ?>"><button class="btn btn-outline-dark btn-sm">Resolve report</button></form></article><?php endforeach; ?></section>
<section class="admin-section"><div class="section-head"><h2>Published rides</h2><span>Latest 100</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Route</th><th>Travel date</th><th>Driver</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($data['admin_rides'] as $ride): ?><tr><td><?= e($ride['origin']) ?> → <?= e($ride['destination']) ?></td><td><?= e(date('M j, Y',strtotime($ride['travel_date']))) ?></td><td><?= e($ride['driver_name']) ?></td><td><span class="status status-<?= strtolower($ride['status']) ?>"><?= e($ride['status']) ?></span></td><td><?php if($ride['status']==='Open'): ?><form method="post" data-confirm="Cancel this ride and all pending/confirmed bookings?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="admin_cancel_ride"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="ride_id" value="<?= (int)$ride['id'] ?>"><button class="btn btn-link btn-sm text-danger">Cancel ride</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-section"><div class="section-head"><h2>Booking requests</h2><span>Latest 100</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Route</th><th>Passenger</th><th>Driver</th><th>Seats</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($data['admin_bookings'] as $booking): ?><tr><td><?= e($booking['origin']) ?> → <?= e($booking['destination']) ?></td><td><?= e($booking['passenger_name']) ?></td><td><?= e($booking['driver_name']) ?></td><td><?= (int)$booking['seats'] ?></td><td><span class="status status-<?= strtolower($booking['status']) ?>"><?= e($booking['status']) ?></span></td><td><?php if(in_array($booking['status'],['Pending','Confirmed'],true)): ?><form method="post" data-confirm="Cancel this booking?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="admin_cancel_booking"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><button class="btn btn-link btn-sm text-danger">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-section"><div class="section-head"><h2>Emergency reports</h2><span><?= count(array_filter($data['emergency_reports'],fn($report)=>$report['status']==='Open')) ?> open</span></div><?php if(!$data['emergency_reports']): ?><p class="muted">No emergency reports have been submitted.</p><?php endif; ?><?php foreach($data['emergency_reports'] as $report): ?><article class="complaint-row"><div><span class="status status-<?= strtolower($report['status']) ?>"><?= e($report['status']) ?></span><p><?= nl2br(e($report['details'])) ?></p><small><?= e($report['user_name']??'Guest user') ?> · <?= e(date('M j, Y g:i a',strtotime($report['created_at']))) ?></small></div><?php if($report['status']==='Open'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="resolve_emergency"><input type="hidden" name="return_page" value="admin"><input type="hidden" name="report_id" value="<?= (int)$report['id'] ?>"><button class="btn btn-outline-dark btn-sm">Mark reviewed</button></form><?php endif; ?></article><?php endforeach; ?></section>